    assert top_n([5, 5, 4, 3, 3], 3) == [5, 5, 4]

def test_top_n_n_larger_than_size():
    assert top_n([1, 2, 3], 5) == [3, 2, 1]

def test_top_n_zero():
    assert top_n([1, 2, 3], 0) == []

def test_top_n_empty():
    assert top_n([], 3) == []
