import os
import importlib.util
import pytest

TARGET_CODE_PATH = os.environ['TARGET_CODE_PATH']
spec = importlib.util.spec_from_file_location('target_module', TARGET_CODE_PATH)
target = importlib.util.module_from_spec(spec)
spec.loader.exec_module(target)
is_strong_password = target.is_strong_password

def test_strong_password():
    assert is_strong_password("Strong1!") is True

def test_too_short():
    assert is_strong_password("Str1!") is False

def test_missing_upper():
    assert is_strong_password("strong1!") is False

def test_missing_lower():
    assert is_strong_password("STRONG1!") is False

def test_missing_digit():
    assert is_strong_password("Strong!") is False

def test_missing_symbol():
    assert is_strong_password("Strong123") is False

def test_boundary_length_8():
    assert is_strong_password("Ab1!5678") is True

def test_boundary_length_7():
    assert is_strong_password("Ab1!567") is False

def test_empty_string():
    assert is_strong_password("") is False

def test_non_string_input():
    with pytest.raises(TypeError):
        is_strong_password(12345678)

